export const BODY: string = "\n<p>بوابتك تريد 80 كيلوبايت. ليس 50 ولا 100، بل 80 بالضبط. أدوات الأحجام الثابتة لا تستطيع ذلك، لكن أداة الهدف المخصص تستطيع.</p>\n<p>ضاغط حجم الملف المستهدف يحل هذه المشكلة. تكتب الرقم الدقيق، وتشغّل البحث، وتحصل على ملف يناسب الحد تمامًا.</p>\n<p>يمر هذا الدليل بالعملية كاملة، من قراءة قواعد البوابة إلى التحقق من الملف النهائي بالبايتات.</p>\n<h2 id=\"what-you-need\">ما الذي تحتاجه قبل البدء؟</h2>\n<p>تحتاج إلى معرفة حد البوابة الدقيق والصيغة المقبولة، والصورة الأصلية بأعلى جودة، ومتصفح حديث. هذه الثلاثة تكفي للبدء.</p>\n<p>اقرأ قواعد البوابة بعناية قبل البدء: الحد الأقصى للحجم، والأبعاد المطلوبة، والصيغة المقبولة. هذه التفاصيل تحدد كل خطوة لاحقة.</p>\n<h2 id=\"step-1-open\">الخطوة 1: افتح ضاغط الهدف</h2>\n<p>افتح <a href=\"/ar/daght-as-sura-ila-hajm-muayyan/\">ضاغط حجم الملف المستهدف</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصورة إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تثبيت. افتح الصفحة وابدأ فورًا، وستبقى صورتك خاصة طوال العملية.</p>\n<h2 id=\"step-2-type-target\">الخطوة 2: اكتب هدفك الدقيق</h2>\n<p>اكتب هدفك الدقيق في خانة الحجم، مثل 80، واختر وحدة الكيلوبايت. تحقق من الوحدة مرتين، فالخلط بين الكيلوبايت والميغابايت خطأ شائع.</p>\n<p>إذا كان هدفك غير معتاد مثل 120 أو 150 كيلوبايت، فهذه الأداة هي الخيار الصحيح. الأدوات الثابتة لا تقدم هذه الأرقام.</p>\n<h2 id=\"step-3-upload\">الخطوة 3: ارفع صورتك</h2>\n<p>ارفع صورتك إلى الأداة. تُقبل ملفات JPG وPNG وWebP وHEIC، بحجم إدخال يصل إلى 25 ميغابايت.</p>\n<p>إذا كانت صورتك لقطة شاشة، فابحث عن الملف الأصلي بدلها. لقطات الشاشة تحمل ضجيجًا يجعل الوصول إلى الهدف أصعب.</p>\n<h2 id=\"step-4-format\">الخطوة 4: اختر صيغة الإخراج</h2>\n<p>للصور الفوتوغرافية اختر JPG. يعطي أصغر ملف بأفضل جودة، وتقبله كل البوابات دون استثناء تقريبًا.</p>\n<p>للنصوص والرسوم المسطحة اختر PNG، وللشعارات الشفافة جرّب WebP إذا قبلته بوابتك. اختيار الصيغة الصحيح يختصر نصف المشكلة.</p>\n<h2 id=\"step-5-run\">الخطوة 5: نفّذ الضغط</h2>\n<p>اضغط زر الضغط واترك الأداة تعمل. تبحث تلقائيًا عن أعلى جودة تناسب هدفك الدقيق، فلا تحتاج إلى تخمين الأرقام.</p>\n<p>تستغرق العملية ثواني معدودة لصورة واحدة. الصور الكبيرة جدًا قد تأخذ وقتًا أطول قليلًا، لكنها تنتهي بسرعة عادة.</p>\n<h2 id=\"step-6-preview\">الخطوة 6: راجع النتيجة بعناية</h2>\n<p>قبل التنزيل، قارن النتيجة بالأصل. كبّر الصورة وافحص الوجه أو النص، وتأكد من أن التفاصيل المهمة ما زالت واضحة.</p>\n<p>تحقق أيضًا من حجم الملف بالبايتات. إذا كان أقل من هدفك بقليل، فهذا هو المطلوب: الأداة تستهدف أقل بقليل لضمان الاجتياز.</p>\n<h2 id=\"step-7-download\">الخطوة 7: نزّل وتحقق</h2>\n<p>نزّل الملف وتأكد من حجمه بالبايتات قبل رفعه. افتح خصائص الملف وتحقق من العدد الدقيق، لا من التقريب.</p>\n<p>سمِّ الملف باسم واضح يذكر الهدف، مثل sora-80kb.jpg. الاسم الواضح يمنع الخلط عندما تحتاج الملف بعد أشهر.</p>\n<h2 id=\"fixing-misses\">كيف تحل مشكلة الهدف غير المحقق؟</h2>\n<p>إذا ظهر تحذير الهدف غير المحقق، فغيّر الصيغة إلى JPG أولًا. PNG هو السبب الأكثر شيوعًا لفشل الوصول إلى الأهداف الصغيرة.</p>\n<p>وإذا استمرت المشكلة، اسمح بتقليص الأبعاد أو قصّ الصورة بإحكام. كل بكسل تزيله يحرّر مساحة من ميزانية الهدف.</p>\n<h2 id=\"batch-exact\">كيف تضغط دفعة إلى حجم دقيق؟</h2>\n<p>لضغط دفعة إلى حجم دقيق، ارفع كل الصور وحدد الهدف نفسه للجميع. كل صورة تُضغط إلى الحجم المخصص الذي حددته.</p>\n<p>راجع عينة من النتائج قبل الاعتماد على الدفعة كلها. إذا بدت العينة جيدة، فغالبًا بقية الصور بنفس الجودة.</p>\n<h2 id=\"changing-target\">كيف تغيّر الهدف بعد الضغط؟</h2>\n<p>يمكنك تغيير الهدف بعد الضغط دون إعادة رفع الصورة. غيّر الرقم في خانة الهدف وشغّل الضغط مجددًا من الملف المرفوع نفسه.</p>\n<p>هذه المرونة مفيدة عندما تغيّر البوابة حدها أو عندما تكتشف أن هدفك الأول لم يكن مناسبًا.</p>\n<h2 id=\"phone-workflow\">سير العمل: على هاتفك</h2>\n<p>كل الخطوات تعمل على الهاتف. افتح الأداة في المتصفح واكتب هدفك، ثم ارفع الصورة من معرضك وعاين النتيجة ونزّلها.</p>\n<p>على الشاشات الصغيرة، تأكد من كتابة الرقم والوحدة بشكل صحيح. خطأ في الوحدة على الهاتف سهل الحدوث.</p>\n<h2 id=\"reading-portal-rules\">كيف تقرأ قواعد البوابة كقائمة تحقق؟</h2>\n<p>اقرأ قواعد البوابة كقائمة تحقق: الحد الأقصى للحجم، والأبعاد المطلوبة، والصيغة المقبولة، وعدد الملفات المسموح بها.</p>\n<p>حوّل كل قاعدة إلى خطوة في سير عملك. القائمة الواضحة تمنع نسيان تفصيل مهم تحت ضغط الموعد النهائي.</p>\n<h2 id=\"odd-targets\">أهداف غريبة: 80 و120 و150 كيلوبايت</h2>\n<p>الأهداف الغريبة مثل 80 و120 و150 كيلوبايت شائعة في البوابات الحكومية وبوابات الامتحانات. لا تستغرب منها، فأداة الهدف المخصص صُممت لها.</p>\n<p>اكتب الرقم كما هو في قواعد البوابة، واستهدف أقل بقليل لضمان الاجتياز. الفارق البسيط يحميك من اختلاف أنظمة التقريب.</p>\n<h2 id=\"verifying-bytes\">كيف تتحقق من النتيجة بالبايتات الدقيقة؟</h2>\n<p>للتحقق من النتيجة بالبايتات الدقيقة، افتح خصائص الملف على جهازك. الرقم المعروض هناك هو ما تفحصه البوابة.</p>\n<p>لا تعتمد على تقريب جهازك أو المتصفح. البوابات تفحص العدد الدقيق للبايتات، وملف 79 كيلوبايت يجتاز بينما ملف 81 كيلوبايت يُرفض.</p>\n<h2 id=\"signature-exact\">التوقيعات إلى حجم دقيق بالكيلوبايت</h2>\n<p>التوقيعات إلى حجم دقيق سهلة لأنها معظمه مساحة بيضاء. امسح التوقيع بدقة معتدلة واحفظه بصيغة JPG، ثم اضغطه إلى الهدف.</p>\n<p>إذا كان الهدف صغيرًا جدًا مثل 20 كيلوبايت، فقصّ التوقيع بإحكام حول الحبر. المساحة البيضاء الزائدة تهدر ميزانية الهدف.</p>\n<h2 id=\"documents-exact\">المستندات إلى حجم دقيق بالكيلوبايت</h2>\n<p>المستندات إلى حجم دقيق تحتاج عناية بالنص. حافظ على الأبعاد كبيرة وخفض الجودة تدريجيًا، لأن النص يتحسس من فقدان الحدة.</p>\n<p>إذا أصبح النص غير مقروء، فجرّب PNG بدل JPG. الرسوم والنصوص تتحمل PNG أفضل، رغم حجمه الأكبر.</p>\n<h2 id=\"retry-strategy\">استراتيجية إعادة المحاولة للأهداف غير المحققة</h2>\n<p>استراتيجية إعادة المحاولة للأهداف غير المحققة: غيّر شيئًا واحدًا في كل مرة. ابدأ بالصيغة، ثم القص، ثم الأبعاد.</p>\n<p>تغيير شيء واحد في كل مرة يخبرك بما حل المشكلة. تغيير كل شيء دفعة واحدة يخفي السبب الحقيقي.</p>\n<h2 id=\"keeping-records\">كيف تحتفظ بسجل للأهداف الدقيقة؟</h2>\n<p>احتفظ بسجل لأهدافك الدقيقة: البوابة، والهدف، والصيغة، والنتيجة. السجل يختصر العمل عندما تتقدم إلى البوابة نفسها مجددًا.</p>\n<p>سمِّ الملفات حسب الهدف والبوابة، مثل sora-bawaba-80kb.jpg. التسمية الواضحة تمنع استخدام الملف الخاطئ.</p>\n<h2 id=\"final-check-exact\">مراجعة أخيرة قبل الإرسال</h2>\n<p>قبل الإرسال، تأكد من ثلاثة أشياء: الحجم أقل من الهدف بالبايتات، والصيغة مقبولة، والأبعاد مطابقة لقواعد البوابة.</p>\n<p>افتح الملف مرة أخيرة وتأكد من جودته. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-daght-as-sura-ila-hajm-muayyan/\">الدليل الكامل لضاغط حجم الملف المستهدف</a> و<a href=\"/ar/blog/al-bahth-al-thunai-an-al-jawda-li-hadaf-kb-daqiq/\">الأهداف الدقيقة بالكيلوبايت: البحث الثنائي عن الجودة</a>، أو جرّب <a href=\"/ar/daght-as-sura-ila-100kb/\">ضاغط 100 كيلوبايت</a> للأحجام الشائعة.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أضغط صورة إلى 80 كيلوبايت بالضبط؟","answer":"اكتب 80 في خانة الهدف واختر وحدة الكيلوبايت، ثم ارفع صورتك وشغّل الضغط. الأداة تبحث عن أعلى جودة تناسب 80 كيلوبايت وتعطيك النتيجة في ثوانٍ."},{"question":"ماذا لو طلبت بوابتي 75 كيلوبايت وأعطتني الأداة 73 كيلوبايت؟","answer":"لا مشكلة. 73 كيلوبايت أقل من الحد، لذلك تجتاز البوابة. الأداة تستهدف أقل بقليل من الهدف لضمان الاجتياز مهما كان نظام التقريب في البوابة."},{"question":"هل يمكنني تغيير الحجم المستهدف دون رفع الصورة مجددًا؟","answer":"نعم، غيّر الرقم في خانة الهدف دون إعادة رفع الصورة. الأداة تعيد الضغط من الملف المرفوع نفسه بالهدف الجديد."},{"question":"لماذا فشل هدفي 80 كيلوبايت بينما 100 كيلوبايت يعمل؟","answer":"لأن الصورة قد لا تستطيع الوصول إلى 80 كيلوبايت دون فقدان جودة كبير، بينما 100 كيلوبايت يمنحها مساحة كافية. جرّب تغيير الصيغة إلى JPG أو قص الصورة بإحكام أكبر."},{"question":"هل تعمل أداة الهدف أيضًا مع الأحجام بالميغابايت؟","answer":"نعم، اختر وحدة الميغابايت في خانة الهدف واكتب الرقم الذي تريده. الأداة تدعم الأهداف بالكيلوبايت والميغابايت معًا."},{"question":"هل يمكنني استخدام أداة الهدف لشعار PNG شفاف؟","answer":"نعم، لكن اختر WebP أو PNG للحفاظ على الشفافية. JPG لا يدعم الشفافية، فسيملأ المناطق الشفافة بلون خلفية. تحقق من قبول بوابتك لـWebP أولًا."}];
